// The cover page's WordprocessingML, for DOCX files generated by the formal-report export route.
//
// The markdown template marks each cover line with `data-cover-line="<kind>"`. The preview paints
// those lines from `buildCoverCssRules`, and this module emits the same sizes, colours, gaps and
// alignment into `word/document.xml`, so the printed cover matches the one on screen.
//
// Lives in `src/lib` so the cover XML can be unit tested without booting Next.

import { REPORT_COVER_FONT_FAMILY, REPORT_COVER_SCALE } from './reportPageMetrics.js'

function xmlEscape(value) {
    return String(value || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&apos;')
}

function decodeHtmlEntities(value) {
    return String(value || '')
        .replace(/&nbsp;/gi, ' ')
        .replace(/&amp;/gi, '&')
        .replace(/&lt;/gi, '<')
        .replace(/&gt;/gi, '>')
        .replace(/&quot;/gi, '"')
        .replace(/&#39;|&apos;/gi, "'")
}

function stripHtmlTags(value) {
    return decodeHtmlEntities(String(value || '').replace(/<[^>]+>/g, ' '))
        .replace(/\s+/g, ' ')
        .trim()
}

/** A cover-page run: Calibri at the reference cover's size, weight and colour. */
function buildCoverRunXml(text, { bold = false, sizeHalfPoints, color, letterSpacingTwips = 0 }) {
    const value = String(text || '')
    if (!value) return ''

    const props = [
        `<w:rFonts w:ascii="${REPORT_COVER_FONT_FAMILY}" w:hAnsi="${REPORT_COVER_FONT_FAMILY}" w:cs="${REPORT_COVER_FONT_FAMILY}"/>`,
        bold ? '<w:b/>' : '',
        color ? `<w:color w:val="${color}"/>` : '',
        letterSpacingTwips ? `<w:spacing w:val="${letterSpacingTwips}"/>` : '',
        `<w:sz w:val="${sizeHalfPoints}"/><w:szCs w:val="${sizeHalfPoints}"/>`,
    ].join('')

    return `<w:r><w:rPr>${props}</w:rPr><w:t xml:space="preserve">${xmlEscape(value)}</w:t></w:r>`
}

/** Splits a cover line's inline HTML into runs, keeping `<br>` breaks and `<strong>` emphasis. */
function buildCoverRunsXml(innerHtml, metrics) {
    const source = String(innerHtml || '')
    const baseRun = {
        bold: Boolean(metrics.bold),
        sizeHalfPoints: Math.round(metrics.sizePoints * 2),
        color: metrics.color,
        letterSpacingTwips: metrics.letterSpacingPoints ? Math.round(metrics.letterSpacingPoints * 20) : 0,
    }
    const leadRun = {
        bold: true,
        sizeHalfPoints: Math.round((metrics.leadSizePoints || metrics.sizePoints) * 2),
        color: metrics.leadColor || metrics.color,
    }

    const runs = []
    const pattern = /<br\s*\/?>|<strong[^>]*>([\s\S]*?)<\/strong>|([^<]+)/gi
    let match
    while ((match = pattern.exec(source)) !== null) {
        if (/^<br/i.test(match[0])) {
            runs.push('<w:r><w:br/></w:r>')
        } else if (match[1] !== undefined) {
            runs.push(buildCoverRunXml(stripHtmlTags(match[1]), leadRun))
        } else if (match[2] !== undefined) {
            runs.push(buildCoverRunXml(decodeHtmlEntities(match[2]).replace(/\s*\r?\n\s*/g, ' '), baseRun))
        }
    }

    // An empty cover line still needs a run so Word keeps the paragraph height.
    return runs.length > 0 ? runs.join('') : buildCoverRunXml(' ', baseRun)
}

/** A centred cover line (`data-cover-line="<kind>"`) as a Word paragraph. */
export function buildWordCoverParagraphXml(kind, innerHtml) {
    const metrics = REPORT_COVER_SCALE[String(kind || '').trim().toLowerCase()]
    if (!metrics) return ''

    const beforeTwips = Math.round((metrics.beforePoints || 0) * 20)
    const afterTwips = Math.round((metrics.afterPoints || 0) * 20)
    const lineTwips = Math.round((metrics.linePoints || 0) * 20)
    const lineXml = lineTwips ? ` w:line="${lineTwips}" w:lineRule="exact"` : ''

    return `<w:p><w:pPr><w:spacing w:before="${beforeTwips}" w:after="${afterTwips}"${lineXml}/><w:jc w:val="center"/></w:pPr>${buildCoverRunsXml(innerHtml, metrics)}</w:p>`
}

/** The cover's full-width navy rule, drawn as the bottom border of a hairline paragraph. */
export function buildWordCoverRuleXml() {
    const rule = REPORT_COVER_SCALE.rule
    const afterTwips = Math.round(rule.afterPoints * 20)
    const sizeEighths = Math.max(1, Math.round(rule.thicknessPoints * 8))
    return `<w:p><w:pPr><w:pBdr><w:bottom w:val="single" w:sz="${sizeEighths}" w:space="0" w:color="${rule.color}"/></w:pBdr><w:spacing w:before="0" w:after="${afterTwips}" w:line="40" w:lineRule="exact"/></w:pPr></w:p>`
}
